use crate::span;

// This file is captured by rustc.  bind may rewrite emit.lst later, but that
// must not change the hopper already compiled into gasketd.
const RAW: &str = include_str!("../loomkit/emit.lst");

#[derive(Clone)]
pub struct Slot {
    pub label: String,
    pub reply: String,
}

impl Default for Slot {
    fn default() -> Self {
        Self {
            label: String::new(),
            reply: "fallthrough".to_string(),
        }
    }
}

fn parse_line(line: &str) -> Option<(u8, Slot)> {
    let mut parts = line.split('\t');
    let label = parts.next()?.trim().to_string();
    let wire: u8 = parts.next()?.trim().parse().ok()?;
    let reply = parts.next()?.trim().to_string();
    if label.is_empty() || reply.is_empty() {
        return None;
    }
    Some((wire, Slot { label, reply }))
}

pub fn rib_b() -> Vec<Slot> {
    let cap = span::rib_a();
    let mut slots = vec![Slot::default(); cap];
    for line in RAW.lines().filter(|line| !line.trim().is_empty()) {
        if let Some((wire, slot)) = parse_line(line) {
            let index = wire as usize;
            if index < slots.len() {
                slots[index] = slot;
            }
        }
    }
    slots
}

pub fn lookup(n: u8) -> Slot {
    rib_b().get(n as usize).cloned().unwrap_or_default()
}

pub fn tap(n: i64) -> i32 {
    let row = if (0..=u8::MAX as i64).contains(&n) {
        lookup(n as u8)
    } else {
        Slot::default()
    };
    println!("{{\"wire\":{},\"reply\":\"{}\"}}", n, row.reply);
    0
}
EOF
