use crate::cards;
use crate::loom;
use crate::table;
use crate::tally;
use std::fs;

pub fn rib_c() -> i32 {
    let _ = tally::lines();
    let _ = loom::emit();
    let spec = cards::load();

    // A card is served only when the immutable, compiled hopper has that
    // card's own label and reply at its WIRE.  The roster is deliberately not
    // used as dispatch state: bind may contain cards added after compilation.
    let sealed = spec.iter().all(|row| {
        let slot = table::lookup(row.wire);
        slot.label == row.label && slot.reply == row.reply && slot.reply != "fallthrough"
    });

    let served = spec
        .iter()
        .map(|row| format!("\"{}\"", row.label))
        .collect::<Vec<_>>()
        .join(",");
    let status = if sealed { "sealed" } else { "open" };
    let text = format!("{{\"served\":[{}],\"status\":\"{}\"}}\n", served, status);
    let _ = fs::create_dir_all("/app/corkbay");
    if fs::write("/app/corkbay/seal.json", text).is_err() {
        return 1;
    }
    if sealed { 0 } else { 1 }
}
EOF
